var e={"ph-meditations-6-48":{e:`app-es-secular`,t:[`Cuando quieras levantar el ánimo, piensa en las buenas cualidades de las personas con quienes convives: la energía de una, la modestia de otra, la generosidad de otra más. Nada alegra tanto el corazón como las virtudes que se ven en el carácter de quienes nos rodean.`]},"ph-analects-4-21":{e:`app-es-secular`,t:[`El Maestro dijo: «Debes saber siempre la edad de tus padres: por un lado te alegra que hayan vivido tanto, y por otro te hace cuidar de ellos a medida que envejecen».`]},"ph-epicurus-55":{e:`app-es-secular`,t:[`Debemos aliviar nuestras desgracias recordando con gratitud los bienes que hemos perdido y aceptando que lo sucedido no puede deshacerse.`]},"ph-seneca-81":{e:`app-es-secular`,t:[`Nada es más honroso que un corazón agradecido. Quien recuerda un favor ya se enriquece por dentro con solo recordarlo.`]},"ph-amicitia-20":{e:`app-es-secular`,t:[`Fuera de la sabiduría, creo que nada mejor que la amistad se ha dado a los seres humanos.`]},"ph-analects-2-17":{e:`app-es-secular`,t:[`El Maestro dijo: «You, ¿te enseño qué es saber? Decir que sabes cuando sabes, y decir que no sabes cuando no sabes: eso es saber».`]},"ph-analects-7-22":{e:`app-es-secular`,t:[`El Maestro dijo: «Cuando caminamos tres juntos, sin duda hay entre ellos alguien que me enseña. Escojo lo bueno y lo sigo, y lo que no es bueno me sirve para corregirme».`]},"ph-daodejing-22":{e:`app-es-secular`,t:[`Sin exhibirse, se le ve con claridad; sin creerse en lo cierto, brilla; sin jactarse, tiene mérito; sin engrandecerse, perdura. Porque no compite, nadie en el mundo puede competir con esa persona.`]},"ph-enchiridion-46":{e:`app-es-secular`,t:[`Nunca te llames filósofo ni sermonees a la gente sobre principios. Mejor actúa según ellos. Las ovejas no devuelven la hierba para mostrar al pastor cuánto comieron; la digieren por dentro y dan lana y leche.`]},"ph-mencius-3-8":{e:`app-es-secular`,t:[`Mencio dijo: «Cuando le señalaban sus faltas, Zilu se alegraba. Cuando Yu oía buenas palabras, hacía una reverencia. El gran Shun fue aún más lejos: hacía el bien junto con los demás, se dejaba a un lado para seguirles y disfrutaba tomando de otros lo bueno para hacer el bien».`]},"ph-analects-9-28":{e:`app-es-secular`,t:[`El Maestro dijo: «Solo cuando el año se vuelve frío vemos que el pino y el ciprés son los últimos en marchitarse».`]},"ph-analects-2-24":{e:`app-es-secular`,t:[`Ver lo que es justo y no hacerlo es falta de valentía.`]},"ph-mencius-12-15":{e:`app-es-secular`,t:[`Cuando el Cielo va a confiar a alguien una gran tarea, primero inquieta su mente, cansa su cuerpo y deja que sus esfuerzos se tuerzan. Así despierta su corazón, fortalece su paciencia y le hace capaz de lo que antes no podía.`]},"ph-meditations-5-1":{e:`app-es-secular`,t:[`Al amanecer, cuando te cueste levantarte, piensa: «Me levanto para hacer el trabajo de un ser humano». ¿Por qué quejarme de ir a hacer aquello para lo que nací? ¿Fui hecho para quedarme bajo las mantas, calentito?`]},"ph-seneca-13":{e:`app-es-secular`,t:[`Hay más cosas que nos asustan que cosas que nos aplastan, y sufrimos más a menudo en la imaginación que en la realidad. No te hagas infeliz de antemano por lo que aún no ha llegado.`]},"ph-analects-15-24":{e:`app-es-secular`,t:[`Zigong preguntó: «¿Hay una palabra que se pueda practicar toda la vida?». El Maestro dijo: «Quizá sea la reciprocidad: lo que no deseas para ti, no lo hagas a los demás».`]},"ph-meditations-6-6":{e:`app-es-secular`,t:[`La mejor manera de responder a quien te ha hecho daño es no volverte como esa persona.`]},"ph-meditations-2-1":{e:`app-es-secular`,t:[`Dite cada mañana: hoy me encontraré con gente entrometida, desagradecida, arrogante, envidiosa. Actúan así porque no saben qué es bueno y qué es malo. Pero no pueden dañarme, ni puedo enojarme con quienes comparten mi naturaleza, porque nacimos para colaborar.`]},"ph-analects-15-15":{e:`app-es-secular`,t:[`El Maestro dijo: «Exígete mucho a ti y poco a los demás, y el resentimiento se mantendrá lejos».`]},"ph-meditations-7-22":{e:`app-es-secular`,t:[`Es propio del ser humano amar incluso a quien tropieza. Puedes hacerlo si recuerdas que son de tu misma familia, que se equivocan por ignorancia y sin querer, y sobre todo que no han dañado en nada tu interior.`]},"ph-analects-1-1":{e:`app-es-secular`,t:[`El Maestro dijo: «¿No es una alegría aprender y, a su tiempo, poner en práctica lo aprendido? ¿No es un gozo que llegue un amigo de lejos? ¿No es propio de una persona noble no sentir rencor cuando los demás no le reconocen?».`]},"ph-daodejing-33":{e:`app-es-secular`,t:[`Quien conoce a los demás es sabio; quien se conoce a sí es lúcido. Quien vence a los demás tiene fuerza; quien se vence a sí es fuerte. Quien sabe cuándo es suficiente es rico.`]},"ph-enchiridion-5":{e:`app-es-secular`,t:[`Lo que perturba a las personas no son las cosas mismas, sino sus juicios sobre ellas. Así que, cuando estemos inquietos o molestos, no culpemos a otros: miremos dentro, es decir, a nuestros propios juicios.`]},"ph-analects-2-15":{e:`app-es-secular`,t:[`El Maestro dijo: «Aprender sin pensar te deja a oscuras; pensar sin aprender te pone en peligro».`]},"ph-pensees-347":{e:`app-es-secular`,t:[`El ser humano no es más que una caña, lo más débil de la naturaleza; pero es una caña que piensa.`]},"ph-daodejing-81":{e:`app-es-secular`,t:[`La persona sabia no acumula. Cuanto más hace por los demás, más tiene; cuanto más da a los demás, más abundancia le queda.`]},"ph-mencius-1-7":{e:`app-es-secular`,t:[`Extiende el respeto que muestras a los mayores de tu familia a los mayores de otras familias, y el cariño que das a tus propios niños a los niños de los demás, y el mundo podrá moverse en la palma de tu mano.`]},"ph-seneca-6":{e:`app-es-secular`,t:[`Me alegra aprender algo sobre todo porque puedo enseñarlo. Ningún bien es agradable de poseer sin alguien con quien compartirlo.`]},"ph-analects-6-30":{e:`app-es-secular`,t:[`Una persona humana, si desea mantenerse firme, ayuda a otros a mantenerse firmes, y si desea lograr algo, ayuda a otros a lograrlo. Saber tomarse a sí como medida para comprender a los demás: ese puede llamarse el camino de la humanidad.`]},"ph-meditations-5-6":{e:`app-es-secular`,t:[`Hay quien, al hacer un favor, espera que se lo devuelvan. Otra persona es como la vid: después de dar sus uvas no pide nada más y vuelve a darlas la temporada siguiente. Así, quien ha hecho el bien no hace alarde y pasa a la siguiente buena obra.`]},"ph-franklin-1":{e:`app-es-secular`,t:[`Templanza. No comas hasta embotarte; no bebas hasta exaltarte.`]},"ph-daodejing-44":{e:`app-es-secular`,t:[`Sabe cuándo es suficiente y no caerás en la deshonra; sabe cuándo parar y no correrás peligro. Así podrás perdurar.`]},"ph-epicurus-68":{e:`app-es-secular`,t:[`Nada es suficiente para quien lo suficiente le parece poco.`]},"ph-meditations-4-24":{e:`app-es-secular`,t:[`Se dice que, si quieres paz interior, hagas pocas cosas. Mejor decir: haz solo lo necesario. La mayor parte de lo que decimos y hacemos no es necesaria; quítalo y tendrás más tiempo y más calma, y menos confusión. Así que a cada paso pregúntate: «¿Esto es necesario?».`]},"ph-seneca-2":{e:`app-es-secular`,t:[`No es pobre quien tiene poco, sino quien desea más.`]},"ph-daodejing-64":{e:`app-es-secular`,t:[`El árbol que apenas se puede abrazar nace de un brote diminuto; la torre de nueve pisos empieza con un montón de tierra; el viaje de mil millas comienza bajo tus pies.`]},"ph-analects-1-4":{e:`app-es-secular`,t:[`El maestro Zeng dijo: «Cada día me examino en tres puntos: al trabajar para otros, ¿no he dado lo mejor de mí? Con mis amigos, ¿no he cumplido mi palabra? ¿No he puesto en práctica lo que me enseñaron?».`]},"ph-brevitate-9":{e:`app-es-secular`,t:[`El mayor derroche de la vida es aplazar. Nos quita cada día en cuanto llega y nos roba el presente prometiendo el futuro. El mayor obstáculo para vivir es la espera, que se aferra al mañana y pierde el hoy. Vive ahora.`]},"ph-franklin-6":{e:`app-es-secular`,t:[`Laboriosidad. No pierdas el tiempo; ocúpate siempre en algo útil; elimina toda acción innecesaria.`]},"ph-seneca-1":{e:`app-es-secular`,t:[`Recupérate a ti. Reúne y guarda el tiempo que hasta ahora te quitaban o se te escapaba. El tiempo que más perdemos es el que dejamos pasar sin pensar. Aférrate al día de hoy y dependerás menos del mañana.`]},"ph-analects-13-17":{e:`app-es-secular`,t:[`Cuando Zixia fue nombrado gobernador de Jufu y preguntó sobre el gobierno, el Maestro dijo: «No te apresures ni busques pequeñas ganancias. Si te apresuras, no llegarás; si buscas pequeñas ganancias, no lograrás las cosas grandes».`]},"ph-meditations-10-3":{e:`app-es-secular`,t:[`Todo lo que sucede es algo que por naturaleza puedes soportar o algo que no. Si puedes soportarlo, sopórtalo sin quejarte. Aun cuando parezca insoportable, recuerda que puedes soportar todo lo que tu mente juzgue soportable al ver que hacerlo es por tu bien.`]},"ph-daodejing-63":{e:`app-es-secular`,t:[`Planea lo difícil mientras es fácil; haz lo grande mientras es pequeño. Las cosas difíciles del mundo siempre nacen de lo fácil, y las grandes siempre nacen de lo pequeño.`]},"ph-mencius-13-29":{e:`app-es-secular`,t:[`Mencio dijo: «Emprender algo es como cavar un pozo. Si cavas nueve brazas de hondo pero te detienes antes de llegar al manantial, sigue siendo un pozo abandonado».`]},"ph-enchiridion-10":{e:`app-es-secular`,t:[`Pase lo que pase, pregúntate qué capacidad tienes para afrontarlo. Ante la dificultad encontrarás resistencia; ante el insulto, paciencia. Cuando te acostumbres, las apariencias no te arrastrarán.`]},"ph-meditations-4-3":{e:`app-es-secular`,t:[`La gente busca retiros en el campo, junto al mar, en las montañas. Pero tú puedes retirarte dentro de ti cuando quieras. No hay lugar más tranquilo ni más libre de preocupaciones adonde retirarse que la propia mente. Así que date a menudo ese retiro y renuévate.`]},"ph-daodejing-16":{e:`app-es-secular`,t:[`Alcanza el vacío más hondo; aférrate a la quietud. Los diez mil seres surgen juntos, y yo los veo regresar. Las cosas florecen en abundancia, pero cada una vuelve a su raíz. Volver a la raíz se llama quietud.`]},"ph-analects-7-37":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble es serena y de corazón amplio; la persona mezquina siempre está ansiosa y llena de preocupación».`]},"ph-pensees-139":{e:`app-es-secular`,t:[`He descubierto que toda la infelicidad humana viene de una sola cosa: no saber quedarse tranquilo en una habitación.`]},"ph-zhongyong-14":{e:`app-es-secular`,t:[`Quien se corrige a sí y nada exige a los demás no guarda rencor: arriba no se queja del Cielo; abajo no culpa a nadie.`]},"ph-meditations-4-49":{e:`app-es-secular`,t:[`Sé como el cabo contra el que rompen sin cesar las olas: se mantiene firme y a su alrededor el oleaje se calma. No digas: «Qué desgracia que me haya pasado esto», sino: «Qué suerte que, aunque esto ha pasado, sigo en calma».`]},"ph-analects-4-25":{e:`app-es-secular`,t:[`El Maestro dijo: «La virtud nunca está sola; siempre tiene vecinos».`]},"ph-meditations-8-36":{e:`app-es-secular`,t:[`No te inquietes imaginando toda tu vida de golpe. No reúnas en la mente todas las dificultades que puedan venir; pregunta ante cada cosa presente: «¿Qué hay aquí de insoportable?». Lo que te pesa nunca es el futuro ni el pasado, solo el presente, y el presente se encoge cuando lo miras por sí solo.`]},"ph-amicitia-22":{e:`app-es-secular`,t:[`La amistad hace más brillante la buena fortuna y aligera la adversidad al dividirla y compartir su peso.`]},"ph-meditations-7-64":{e:`app-es-secular`,t:[`Cada vez que llegue el dolor, recuerda que no es nada vergonzoso y que no puede dañar la mente que te guía. Para la mayoría de los dolores, que te ayude Epicuro: el dolor no es insoportable ni interminable, siempre que recuerdes sus límites y no lo agrandes con la imaginación.`]},"ph-analects-9-23":{e:`app-es-secular`,t:[`El Maestro dijo: «La gente joven merece nuestro respeto. ¿Cómo sabemos que quienes vienen detrás no igualarán a los de hoy?».`]},"ph-meditations-7-59":{e:`app-es-secular`,t:[`Mira dentro. Dentro está el manantial del bien, y siempre brotará si sigues cavando.`]},"ph-daodejing-41":{e:`app-es-secular`,t:[`El gran cuadrado no tiene esquinas; la gran vasija se completa tarde; el gran sonido apenas se oye; la gran imagen no tiene forma.`]},"ph-analects-9-19":{e:`app-es-secular`,t:[`El Maestro dijo: «Es como levantar un montículo: si me detengo cuando falta un solo cesto de tierra, soy yo quien se ha detenido. Es como nivelar el suelo: si solo he echado un cesto de tierra pero sigo adelante, soy yo quien ha avanzado».`]},"ph-zhongyong-20":{e:`app-es-secular`,t:[`Si otros lo logran en un intento, yo lo haré cien veces; si otros lo logran en diez, yo lo haré mil. Quien de verdad siga este camino, aunque sea lento, sin duda verá con claridad; aunque sea débil, sin duda se hará fuerte.`]},"ph-analects-1-2":{e:`app-es-secular`,t:[`El maestro You dijo: «Pocas personas que aman a sus padres y respetan a sus mayores gustan de desafiar a quienes están por encima, y nadie que evite desafiarles ha gustado nunca de sembrar desorden. La persona noble trabaja en la raíz; cuando la raíz está firme, de ella nace el camino. El amor a los padres y el respeto a los mayores, ¿no son la raíz de la humanidad?».`]},"ph-analects-1-3":{e:`app-es-secular`,t:[`El Maestro dijo: «Palabras astutas y rostro complaciente: rara vez hay humanidad en ellos».`]},"ph-analects-1-6":{e:`app-es-secular`,t:[`El Maestro dijo: «Que la gente joven ame a sus padres en casa y respete a sus mayores fuera, que sea cuidadosa y digna de confianza, que quiera a todo el mundo y se acerque a quienes son humanos. Si después de esto le sobran fuerzas, que estudie».`]},"ph-analects-1-7":{e:`app-es-secular`,t:[`Zixia dijo: «Quien aprecia a las personas valiosas tanto como a la belleza, sirve a sus padres con todas sus fuerzas, se entrega por completo al servir a sus superiores y cumple su palabra con sus amistades: aunque diga que no ha estudiado, yo sin duda diría que tiene saber».`]},"ph-analects-1-12":{e:`app-es-secular`,t:[`El maestro You dijo: «En la práctica del decoro, lo más valioso es la armonía».`]},"ph-analects-1-14":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble no busca hartarse al comer ni comodidad en su morada; es diligente en el trabajo y prudente al hablar, y acude a quienes siguen el camino para corregirse. De alguien así puede decirse que ama aprender».`]},"ph-analects-1-15":{e:`app-es-secular`,t:[`Zigong preguntó: «Ser pobre sin adular, ser rico sin arrogancia, ¿qué tal es?». El Maestro dijo: «Está bien, pero no tanto como ser pobre y alegre, rico y amante del decoro». Zigong dijo: «El Libro de las Odas dice: "Como cortado, como limado, como tallado, como pulido". ¿Es eso lo que significa?». El Maestro dijo: «Ci, ahora sí puedo hablar contigo de las Odas. Al decirte lo pasado, comprendes lo que vendrá».`]},"ph-analects-1-16":{e:`app-es-secular`,t:[`El Maestro dijo: «No te preocupes de que los demás no te conozcan; preocúpate de no conocer a los demás».`]},"ph-analects-2-4":{e:`app-es-secular`,t:[`El Maestro dijo: «A los quince años puse mi corazón en aprender; a los treinta me mantuve firme; a los cuarenta dejé de dudar; a los cincuenta comprendí el mandato del Cielo; a los sesenta mi oído se volvió dócil; a los setenta podía seguir los deseos de mi corazón sin traspasar lo justo».`]},"ph-analects-2-7":{e:`app-es-secular`,t:[`Ziyou preguntó por el amor filial. El Maestro dijo: «Hoy se llama amor filial a poder mantener a los padres. Pero incluso a perros y caballos se les mantiene. Sin respeto, ¿dónde está la diferencia?».`]},"ph-analects-2-10":{e:`app-es-secular`,t:[`El Maestro dijo: «Mira lo que alguien hace, observa por qué lo hace y examina con qué se siente en paz. ¿Cómo podría ocultarse? ¿Cómo podría ocultarse?».`]},"ph-analects-2-11":{e:`app-es-secular`,t:[`El Maestro dijo: «Quien repasa lo antiguo para comprender lo nuevo puede ser maestro».`]},"ph-analects-2-12":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble no es un recipiente hecho para un solo uso».`]},"ph-analects-2-13":{e:`app-es-secular`,t:[`Zigong preguntó por la persona noble. El Maestro dijo: «Primero pon en práctica tus palabras y después deja que tus palabras sigan».`]},"ph-analects-2-14":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble es abierta con todos y no forma camarillas; la persona mezquina forma camarillas y no es abierta con todos».`]},"ph-analects-2-18":{e:`app-es-secular`,t:[`Zizhang quería aprender a obtener un cargo. El Maestro dijo: «Escucha mucho, deja a un lado lo dudoso y habla con cuidado del resto, y cometerás pocos errores. Observa mucho, deja a un lado lo arriesgado y actúa con cuidado en lo demás, y tendrás pocos remordimientos. Con pocos errores al hablar y pocos remordimientos al actuar, el cargo llegará».`]},"ph-analects-2-22":{e:`app-es-secular`,t:[`El Maestro dijo: «No sé qué puede hacer una persona sin confianza. Si a un carro grande le falta la clavija del yugo y a uno pequeño la del collar, ¿cómo van a avanzar?».`]},"ph-analects-3-4":{e:`app-es-secular`,t:[`Lin Fang preguntó por la raíz del decoro. El Maestro dijo: «¡Gran pregunta! En el decoro, es mejor la sencillez que el derroche».`]},"ph-analects-4-1":{e:`app-es-secular`,t:[`El Maestro dijo: «Es hermoso vivir entre personas humanas. Si eliges no vivir entre ellas, ¿cómo se te puede llamar sabio?».`]},"ph-analects-4-2":{e:`app-es-secular`,t:[`El Maestro dijo: «Quien carece de humanidad no puede permanecer mucho tiempo en la estrechez ni en la dicha. Las personas humanas descansan en la humanidad; las sabias la encuentran provechosa».`]},"ph-analects-4-5":{e:`app-es-secular`,t:[`El Maestro dijo: «Riqueza y rango son lo que la gente desea, pero si no se obtienen por el camino correcto, no los conserves. Pobreza y humildad son lo que la gente rechaza, pero si no se pueden dejar por el camino correcto, no abandones tu lugar».`]},"ph-analects-4-9":{e:`app-es-secular`,t:[`El Maestro dijo: «Quien ha puesto el corazón en el camino pero se avergüenza de la ropa pobre y la comida sencilla no merece que se converse con esa persona».`]},"ph-analects-4-12":{e:`app-es-secular`,t:[`El Maestro dijo: «Si actúas solo pensando en el provecho, cosecharás mucho resentimiento».`]},"ph-analects-4-14":{e:`app-es-secular`,t:[`El Maestro dijo: «No te preocupes por no tener un puesto; preocúpate por tener lo necesario para ocuparlo. No te preocupes de que nadie te conozca; esfuérzate por merecer ser conocido».`]},"ph-analects-4-15":{e:`app-es-secular`,t:[`El Maestro dijo: «Shen, mi camino está atravesado por un solo hilo». El maestro Zeng respondió: «Sí». Cuando el Maestro salió, los discípulos preguntaron: «¿Qué quiso decir?». El maestro Zeng dijo: «El camino del Maestro es simplemente entrega sincera y comprensión hacia los demás».`]},"ph-analects-4-16":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble entiende lo que es justo; la persona mezquina entiende lo que es provechoso».`]},"ph-analects-4-17":{e:`app-es-secular`,t:[`El Maestro dijo: «Cuando veas a una persona digna, piensa en igualarla; cuando veas a una persona indigna, mira dentro de ti y examínate».`]},"ph-meditations-1-1":{e:`app-es-secular`,t:[`De mi abuelo Vero aprendí el buen carácter y un temple libre de ira.`]},"ph-meditations-1-3":{e:`app-es-secular`,t:[`De mi madre aprendí la reverencia y la generosidad, a abstenerme no solo de hacer el mal sino incluso de pensarlo, y una forma de vida sencilla, lejos de las costumbres de los ricos.`]},"ph-meditations-1-7":{e:`app-es-secular`,t:[`De Rústico aprendí que mi carácter necesitaba corrección y entrenamiento; a leer con atención sin conformarme con una comprensión superficial; y a calmarme con facilidad y estar dispuesto a reconciliarme con quienes me habían ofendido en cuanto quisieran hacer las paces.`]},"ph-meditations-1-8":{e:`app-es-secular`,t:[`De Apolonio aprendí la libertad de espíritu y una firmeza inquebrantable; a no mirar a otra cosa, ni por un momento, que a la razón; y a mantenerme siempre igual, en el dolor agudo y en la enfermedad larga.`]},"ph-meditations-1-15":{e:`app-es-secular`,t:[`De Máximo aprendí el dominio de mí y a no dejarme arrastrar por nada; el buen ánimo en toda circunstancia, también en la enfermedad; un carácter en que se mezclan bien la dulzura y la dignidad; y a hacer sin quejarme el trabajo que tengo delante.`]},"ph-meditations-1-16":{e:`app-es-secular`,t:[`De mi padre aprendí la mansedumbre y la firmeza en las decisiones tomadas tras pensarlo bien; la indiferencia ante los honores aparentes; el amor al trabajo y la constancia en él; y la disposición a escuchar a cualquiera que tuviera algo útil que aportar al bien común.`]},"ph-meditations-1-17":{e:`app-es-secular`,t:[`Tuve buenos abuelos, buenos padres, una buena hermana, buenos maestros, buenos compañeros, parientes y amigos: casi todo bueno. Por ello estoy agradecido.`]},"ph-meditations-3-4":{e:`app-es-secular`,t:[`No malgastes lo que te queda de vida pensando en los demás, salvo que sirva al bien común: qué hace alguien y por qué, qué dice, piensa o planea. Todo eso te aparta de otras tareas.`]},"ph-meditations-4-7":{e:`app-es-secular`,t:[`Quita tu juicio, y desaparece el «me han hecho daño». Quita el «me han hecho daño», y desaparece el daño.`]},"ph-meditations-4-17":{e:`app-es-secular`,t:[`Mientras vivas, mientras aún esté en tu mano, obra el bien.`]},"ph-meditations-4-18":{e:`app-es-secular`,t:[`Cuánto tiempo libre gana quien no se fija en lo que dice, hace o piensa su vecino, sino solo en lo que hace por su parte, para que sea justo y limpio.`]},"ph-meditations-5-5":{e:`app-es-secular`,t:[`Quizá la gente no admire tu ingenio rápido. Está bien. Pero hay muchas cosas de las que no puedes decir «no tengo talento para eso»: honestidad, seriedad, aguante en el trabajo duro, libertad frente al placer, conformidad con tu suerte, necesitar poco, amabilidad, generosidad. Puedes mostrarlas ahora mismo.`]},"ph-meditations-5-9":{e:`app-es-secular`,t:[`No te disgustes, ni te desanimes, ni abandones porque no siempre hayas logrado actuar según principios rectos. Cuando caigas, vuelve otra vez, y alégrate si la mayor parte de lo que haces es digna de un ser humano.`]},"ph-meditations-5-16":{e:`app-es-secular`,t:[`Tu mente tomará el carácter de los pensamientos en los que más te detienes, porque el alma se tiñe de sus pensamientos.`]},"ph-meditations-6-19":{e:`app-es-secular`,t:[`Si algo te resulta difícil, no pienses que es imposible para un ser humano. Si es posible y propio de un ser humano, piensa que también está a tu alcance.`]},"ph-meditations-6-21":{e:`app-es-secular`,t:[`Si alguien puede mostrarme y convencerme de que no pienso o actúo bien, cambiaré con gusto, porque busco la verdad, y nadie salió nunca dañado por la verdad. Quien sale dañado es quien permanece en su propio error e ignorancia.`]},"ph-meditations-6-30":{e:`app-es-secular`,t:[`Conserva en ti la sencillez, la bondad, la limpieza, la seriedad y la naturalidad; el amor a la justicia, la reverencia, la amabilidad, el afecto y la firmeza en hacer lo debido. Esfuérzate por seguir siendo la persona que la filosofía quiso hacer de ti.`]},"ph-meditations-6-53":{e:`app-es-secular`,t:[`Acostúmbrate a prestar mucha atención a lo que dicen los demás y, en lo posible, entra en la mente de quien habla.`]},"ph-meditations-7-8":{e:`app-es-secular`,t:[`No dejes que el futuro te inquiete. Si has de llegar a él, lo afrontarás con la misma razón que ahora usas para el presente.`]},"ph-meditations-7-13":{e:`app-es-secular`,t:[`Así como los miembros forman un solo cuerpo, los seres racionales, aunque separados, están hechos para colaborar. Lo sentirás más hondo si te dices a menudo: «Soy un miembro del cuerpo de los seres racionales». Entonces hacer el bien a la gente se vuelve una alegría en sí.`]},"ph-meditations-7-26":{e:`app-es-secular`,t:[`Cuando alguien te haga daño, considera enseguida qué creía bueno o malo para actuar así. Cuando lo veas, sentirás compasión en lugar de sorpresa o enojo.`]},"ph-meditations-7-27":{e:`app-es-secular`,t:[`No pienses en lo que te falta como si ya lo tuvieras; elige lo mejor de lo que tienes y piensa con cuánto afán lo buscarías si no lo tuvieras. Pero cuida de no aferrarte tanto que te derrumbes si algún día lo pierdes.`]},"ph-meditations-7-71":{e:`app-es-secular`,t:[`Es absurdo no huir de los propios defectos, cosa posible, mientras intentas huir de los defectos ajenos, cosa imposible.`]},"ph-meditations-8-47":{e:`app-es-secular`,t:[`Si algo externo te angustia, no es la cosa en sí lo que te perturba, sino tu juicio sobre ella, y está en tu mano borrar ese juicio ahora mismo.`]},"ph-meditations-8-59":{e:`app-es-secular`,t:[`Las personas existen las unas para las otras. Así que enséñales o ten paciencia con ellas.`]},"ph-meditations-9-6":{e:`app-es-secular`,t:[`Un juicio presente que capta las cosas con verdad, una acción presente dirigida al bien común, una disposición presente que acepta con gusto lo que viene de fuera: eso basta.`]},"ph-meditations-10-16":{e:`app-es-secular`,t:[`Deja ya de discutir cómo debe ser una buena persona. Sé una.`]},"ph-analects-4-18":{e:`app-es-secular`,t:[`El Maestro dijo: «Al servir a tus padres, señala sus errores con suavidad. Si ves que no te siguen, sigue respetándoles sin contrariarles; aunque te canse, no guardes resentimiento».`]},"ph-analects-4-22":{e:`app-es-secular`,t:[`El Maestro dijo: «La gente de antaño no hablaba a la ligera, porque le avergonzaba que sus actos no estuvieran a la altura de sus palabras».`]},"ph-analects-4-23":{e:`app-es-secular`,t:[`El Maestro dijo: «Quien se contiene rara vez se equivoca».`]},"ph-analects-4-24":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble desea ser lenta al hablar y rápida al actuar».`]},"ph-analects-5-12":{e:`app-es-secular`,t:[`Zigong dijo: «Lo que no quiero que otros me hagan, deseo no hacérselo a los demás». El Maestro dijo: «Ci, eso aún está más allá de lo que has alcanzado».`]},"ph-analects-5-15":{e:`app-es-secular`,t:[`Zigong preguntó: «¿Por qué se le dio a Kong Wenzi el nombre de "Wen"?». El Maestro dijo: «Era ágil y amaba aprender, y no le avergonzaba preguntar a quienes estaban por debajo. Por eso se le llamó "Wen"».`]},"ph-analects-5-16":{e:`app-es-secular`,t:[`El Maestro dijo de Zichan: «Tenía cuatro de los caminos de la persona noble: se conducía con cortesía, servía a sus superiores con respeto, cuidaba del pueblo con bondad y empleaba al pueblo con justicia».`]},"ph-analects-5-20":{e:`app-es-secular`,t:[`Ji Wenzi pensaba tres veces antes de actuar. Cuando el Maestro lo supo, dijo: «Con dos basta».`]},"ph-analects-5-23":{e:`app-es-secular`,t:[`El Maestro dijo: «Boyi y Shuqi no guardaban rencor por las faltas pasadas, y por eso hubo poco resentimiento».`]},"ph-analects-5-26":{e:`app-es-secular`,t:[`Yan Yuan y Zilu estaban con el Maestro, quien dijo: «¿Por qué no me dice cada cual lo que desea?». Zilu dijo: «Quisiera compartir mi carro, mis caballos y mis pieles ligeras con mis amistades, y no lamentarlo si se gastan». Yan Yuan dijo: «Quisiera no presumir de mis buenas obras ni cargar a otros con el trabajo pesado». Zilu dijo: «Quisiéramos oír lo que desea usted, Maestro». El Maestro dijo: «Dar tranquilidad a los mayores, merecer la confianza de las amistades y acoger con cariño a los jóvenes».`]},"ph-analects-5-27":{e:`app-es-secular`,t:[`El Maestro dijo: «¡No hay remedio! Aún no he conocido a nadie que sepa ver sus propias faltas y reprenderse por dentro».`]},"ph-analects-5-28":{e:`app-es-secular`,t:[`El Maestro dijo: «En una aldea de diez casas seguro que hay alguien tan leal y digno de confianza como yo, pero no alguien que ame aprender tanto como yo».`]},"ph-analects-6-11":{e:`app-es-secular`,t:[`El Maestro dijo: «¡Qué valioso es Hui! Un cuenco de arroz, una calabaza de agua, una vida en un callejón humilde: otros no soportarían esa estrechez, pero Hui nunca pierde su alegría. ¡Qué valioso es Hui!».`]},"ph-analects-6-12":{e:`app-es-secular`,t:[`Ran Qiu dijo: «No es que no me agrade su camino, Maestro; es que no me alcanzan las fuerzas». El Maestro dijo: «A quien le faltan fuerzas abandona a mitad de camino. Tú te estás poniendo un límite antes de empezar».`]},"ph-analects-6-18":{e:`app-es-secular`,t:[`El Maestro dijo: «Cuando el fondo supera a la forma, se es tosco; cuando la forma supera al fondo, se es ostentoso. Solo cuando forma y fondo están en equilibrio se es una persona noble».`]},"ph-analects-6-20":{e:`app-es-secular`,t:[`El Maestro dijo: «Conocerlo no es tan bueno como amarlo; amarlo no es tan bueno como disfrutarlo».`]},"ph-analects-6-23":{e:`app-es-secular`,t:[`El Maestro dijo: «Las personas sabias se deleitan en el agua; las humanas, en las montañas. Las sabias están en movimiento; las humanas, en calma. Las sabias viven con alegría; las humanas viven largo tiempo».`]},"ph-analects-6-27":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble que estudia ampliamente la cultura y se ciñe con el decoro no se apartará del camino».`]},"ph-analects-6-29":{e:`app-es-secular`,t:[`El Maestro dijo: «¡Qué suprema es la virtud del justo medio! Pero hace mucho que es rara entre la gente».`]},"ph-analects-7-2":{e:`app-es-secular`,t:[`El Maestro dijo: «Guardar las cosas en silencio, aprender sin cansarse, enseñar a otros sin desfallecer: ¿cuál de estas puedo atribuirme?».`]},"ph-analects-7-3":{e:`app-es-secular`,t:[`El Maestro dijo: «No cultivar la virtud, no practicar lo aprendido, oír lo justo y no ir hacia ello, no poder cambiar lo que no es bueno: esas son mis preocupaciones».`]},"ph-analects-7-6":{e:`app-es-secular`,t:[`El Maestro dijo: «Pon tu corazón en el camino, aférrate a la virtud, apóyate en la humanidad y disfruta de las artes».`]},"ph-analects-7-8":{e:`app-es-secular`,t:[`El Maestro dijo: «No abro el camino a quien no está ansioso por aprender, ni ayudo a quien no se esfuerza por expresar lo que piensa. Si muestro una esquina y no sabe volver con las otras tres, no lo repito».`]},"ph-analects-7-16":{e:`app-es-secular`,t:[`El Maestro dijo: «Comer arroz basto y beber agua, con el brazo doblado por almohada: también ahí hay alegría. La riqueza y el rango obtenidos sin justicia son para mí como nubes que pasan».`]},"ph-analects-7-19":{e:`app-es-secular`,t:[`El duque de She preguntó a Zilu por Confucio, y Zilu no respondió. El Maestro dijo: «¿Por qué no dijiste que es alguien que, cuando se entrega a algo, olvida comer, olvida sus preocupaciones en la alegría y no nota que llega la vejez?».`]},"ph-analects-7-20":{e:`app-es-secular`,t:[`El Maestro dijo: «No nací con el saber. Amo lo antiguo y lo busco con diligencia».`]},"ph-analects-7-25":{e:`app-es-secular`,t:[`El Maestro enseñaba cuatro cosas: cultura, conducta, lealtad y confianza.`]},"ph-meditations-9-42":{e:`app-es-secular`,t:[`Cuando te ofenda la desvergüenza de alguien, pregúntate enseguida: «¿Es posible que en el mundo no haya gente desvergonzada?». No lo es. Así que no exijas lo imposible. Esta persona es simplemente una de las que tienen que existir en el mundo.`]},"ph-meditations-11-18":{e:`app-es-secular`,t:[`La mansedumbre genuina y sin fingimiento es invencible. ¿Qué puede hacerte incluso la persona más violenta si sigues siendo amable hasta el final, le corriges con suavidad cuando hay ocasión y, justo cuando intenta dañarte, le muestras con calma otro camino?`]},"ph-meditations-12-4":{e:`app-es-secular`,t:[`Muchas veces me he preguntado cómo es que cada persona se ama más que a nadie y, sin embargo, valora su propia opinión sobre sí menos que la opinión de los demás.`]},"ph-meditations-4-8":{e:`app-es-secular`,t:[`Lo que no hace peor a una persona tampoco empeora su vida; no puede dañarla ni desde fuera ni desde dentro.`]},"ph-meditations-4-31":{e:`app-es-secular`,t:[`Ama el modesto oficio que has aprendido y descansa en él. Vive el resto de tu vida como quien lo ha confiado todo de corazón, sin hacerte amo ni siervo de nadie.`]},"ph-meditations-5-18":{e:`app-es-secular`,t:[`A nadie le sucede nada que su naturaleza no le permita soportar.`]},"ph-meditations-5-20":{e:`app-es-secular`,t:[`La mente convierte lo que estorba su tarea en algo que la sirve, y hace del obstáculo un paso adelante. Lo que se interpone abre el paso; lo que corta el camino se vuelve camino.`]},"ph-meditations-6-7":{e:`app-es-secular`,t:[`Encuentra tu alegría y tu descanso en una sola cosa: pasar de un acto de servicio a los demás al siguiente.`]},"ph-meditations-6-11":{e:`app-es-secular`,t:[`Cuando las circunstancias te obliguen a inquietarte, vuelve pronto a ti y no pierdas el ritmo más de lo necesario. Cuanto más a menudo vuelvas, mejor mantendrás la armonía.`]},"ph-meditations-6-39":{e:`app-es-secular`,t:[`Adáptate a las circunstancias que te han tocado y ama a las personas que el destino ha puesto en tu vida. Pero ámalas de verdad.`]},"ph-meditations-7-5":{e:`app-es-secular`,t:[`¿Me basta mi entendimiento para esta tarea o no? Si basta, lo uso como una herramienta que me dio la naturaleza. Si no, dejo el trabajo a quien pueda hacerlo mejor o, si me toca a mí, hago lo que puedo con ayuda de otra persona. Porque todo lo que haga, a solas o en compañía, debe apuntar solo a lo útil y adecuado para el bien común.`]},"ph-meditations-7-61":{e:`app-es-secular`,t:[`El arte de vivir se parece más a la lucha que a la danza, porque debe mantenerse preparado y firme ante lo que llegue de improviso.`]},"ph-meditations-7-73":{e:`app-es-secular`,t:[`Cuando has hecho una buena obra y otra persona se ha beneficiado, ¿por qué buscar, como hacen los necios, una tercera cosa: fama de bondad o algo a cambio?`]},"ph-meditations-7-74":{e:`app-es-secular`,t:[`Nadie se cansa de recibir un beneficio, y obrar conforme a la naturaleza te beneficia también a ti. Así que no te canses de beneficiar a otros, pues así te beneficias tú.`]},"ph-meditations-8-48":{e:`app-es-secular`,t:[`Una mente libre de pasiones es una ciudadela. No hay lugar más seguro donde una persona pueda refugiarse.`]},"ph-meditations-8-51":{e:`app-es-secular`,t:[`No obres con descuido, ni hables con confusión, ni pienses con dispersión.`]},"ph-meditations-9-11":{e:`app-es-secular`,t:[`Si alguien obra mal, enséñale un camino mejor si puedes. Si no puedes, recuerda que la bondad se te dio precisamente para esto.`]},"ph-meditations-11-9":{e:`app-es-secular`,t:[`Así como quienes se interponen en tu camino no pueden apartarte de la acción recta, no dejes que te quiten tampoco tu buena voluntad hacia ellos. Mantén ambas cosas: firmeza en el juicio y la acción, y mansedumbre hacia quienes intentan estorbarte o molestarte.`]},"ph-meditations-11-13":{e:`app-es-secular`,t:[`¿Alguien me desprecia? Es asunto suyo. Lo mío es no hacer ni decir nada que merezca desprecio. ¿Alguien me odia? También es asunto suyo. Lo mío es ser amable y benévolo con todo el mundo, dispuesto a mostrarle incluso a esa persona su error, sin reproches ni alarde de paciencia, sino con sinceridad y generosidad.`]},"ph-meditations-3-12":{e:`app-es-secular`,t:[`Si haces el trabajo que tienes delante siguiendo la recta razón, con seriedad, vigor y calma, sin dejar que nada te distraiga, manteniendo limpio el bien que hay en ti; si te atienes a esto sin desear ni evitar nada, con la satisfacción de obrar ahora según la naturaleza y con la verdad en lo que dices, vivirás bien. Y nadie puede impedírtelo.`]},"ph-meditations-6-22":{e:`app-es-secular`,t:[`Hago mi parte. Lo demás no me distrae.`]},"ph-meditations-8-8":{e:`app-es-secular`,t:[`No tienes tiempo para leer. Pero sí tienes tiempo para frenar la arrogancia, para estar por encima del placer y del dolor, para ser indiferente a la fama y para no enojarte con quienes no agradecen, e incluso para cuidar de ellos.`]},"ph-meditations-7-65":{e:`app-es-secular`,t:[`Cuida de no sentir hacia quienes carecen de humanidad lo que ellos sienten hacia los demás.`]},"ph-meditations-2-7":{e:`app-es-secular`,t:[`¿Te distraen las cosas que suceden fuera de ti? Entonces date el tiempo de aprender algo nuevo y bueno, y deja de girar de un lado a otro.`]},"ph-meditations-12-19":{e:`app-es-secular`,t:[`Date cuenta por fin de que tienes dentro algo mejor y más divino que las pasiones que te mueven como a una marioneta.`]},"ph-meditations-10-35":{e:`app-es-secular`,t:[`Un ojo sano debe ver todo lo visible y no decir: «Solo quiero cosas verdes». Así también una mente sana debe estar preparada para todo lo que suceda.`]},"ph-meditations-8-16":{e:`app-es-secular`,t:[`Recuerda que cambiar de opinión y seguir a quien te corrige sigue siendo un acto de libertad, porque es tu propia acción, realizada según tu juicio y tu entendimiento.`]},"ph-analects-7-28":{e:`app-es-secular`,t:[`El Maestro dijo: «Quizá haya quien inventa sin saber, pero yo no. Escucho mucho, escojo lo bueno y lo sigo; veo mucho y lo guardo en la memoria. Eso es lo más cercano al saber».`]},"ph-analects-7-30":{e:`app-es-secular`,t:[`El Maestro dijo: «¿Está lejos la humanidad? Si de verdad la deseo, llega de inmediato».`]},"ph-analects-7-34":{e:`app-es-secular`,t:[`El Maestro dijo: «¿Cómo me atrevería a decir que soy sabio o humano? Pero puede decirse de mí que me esfuerzo sin cansarme y enseño a otros sin desfallecer». Gongxi Hua dijo: «Eso es justo lo que los discípulos no logramos aprender».`]},"ph-analects-7-36":{e:`app-es-secular`,t:[`El Maestro dijo: «El derroche lleva a la arrogancia; la austeridad, a la rigidez. Mejor la rigidez que la arrogancia».`]},"ph-analects-7-38":{e:`app-es-secular`,t:[`El Maestro era amable pero firme, digno pero no severo, respetuoso pero sereno.`]},"ph-analects-8-5":{e:`app-es-secular`,t:[`El maestro Zeng dijo: «Siendo capaz, preguntar a quien no lo es; sabiendo mucho, preguntar a quien sabe poco; teniendo, como si no tuviera nada; lleno, como si estuviera vacío; ofendido, sin llevar la cuenta. Hace tiempo tuve un amigo que vivía así».`]},"ph-analects-8-7":{e:`app-es-secular`,t:[`El maestro Zeng dijo: «Quien estudia debe tener amplitud de miras y firmeza, porque la carga es pesada y el camino largo. Toma la humanidad como su carga: ¿no es pesada?».`]},"ph-analects-8-17":{e:`app-es-secular`,t:[`El Maestro dijo: «Estudia como si nunca pudieras alcanzarlo, y aun así teme perder lo que tienes».`]},"ph-analects-9-8":{e:`app-es-secular`,t:[`El Maestro dijo: «¿Tengo saber? No lo tengo. Pero si una persona sencilla me pregunta algo con la mente vacía, examino la cuestión por ambos extremos y hago todo lo posible por responder».`]},"ph-analects-9-17":{e:`app-es-secular`,t:[`De pie junto a un río, el Maestro dijo: «¡Así fluye todo, como esto, sin descanso de día ni de noche!».`]},"ph-analects-9-24":{e:`app-es-secular`,t:[`El Maestro dijo: «¿Cómo no aceptar una advertencia justa? Pero lo valioso es cambiar. ¿Cómo no agradecer un consejo amable? Pero lo valioso es comprenderlo. Si alguien se alegra pero no comprende, acepta pero no cambia, no puedo hacer nada por esa persona».`]},"ph-analects-9-26":{e:`app-es-secular`,t:[`El Maestro dijo: «A un gran ejército se le puede arrebatar su general, pero a nadie, por sencillo que sea, se le puede arrebatar su voluntad».`]},"ph-analects-9-29":{e:`app-es-secular`,t:[`El Maestro dijo: «Quien es sabio no se confunde, quien es humano no se angustia, quien es valiente no teme».`]},"ph-analects-11-16":{e:`app-es-secular`,t:[`Zigong preguntó: «¿Quién es mejor, Zizhang o Zixia?». El Maestro dijo: «Zizhang se pasa; Zixia no llega». Zigong dijo: «¿Entonces Zizhang es mejor?». El Maestro dijo: «Pasarse es lo mismo que no llegar».`]},"ph-analects-12-1":{e:`app-es-secular`,t:[`Yan Yuan preguntó por la humanidad. El Maestro dijo: «Dominarse y volver al decoro es humanidad. Si un solo día te dominas y vuelves al decoro, el mundo entero se volverá hacia la humanidad. Practicar la humanidad depende de ti; ¿cómo va a depender de los demás?».`]},"ph-analects-12-4":{e:`app-es-secular`,t:[`Sima Niu preguntó por la persona noble. El Maestro dijo: «La persona noble no se angustia ni teme». Sima Niu dijo: «¿Basta con no angustiarse ni temer?». El Maestro dijo: «Si miras dentro y no hallas nada de qué avergonzarte, ¿qué hay que te angustie o que temer?».`]},"ph-analects-12-16":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble ayuda a los demás a completar sus buenas cualidades y no favorece las malas. La persona mezquina hace lo contrario».`]},"ph-analects-12-22":{e:`app-es-secular`,t:[`Fan Chi preguntó por la humanidad. El Maestro dijo: «Amar a las personas». Preguntó por la sabiduría. El Maestro dijo: «Conocer a las personas».`]},"ph-analects-12-23":{e:`app-es-secular`,t:[`Zigong preguntó por la amistad. El Maestro dijo: «Aconseja a tu amistad con sinceridad y guíala bien, pero si no escucha, detente, para no buscarte una humillación».`]},"ph-analects-12-24":{e:`app-es-secular`,t:[`El maestro Zeng dijo: «La persona noble reúne amistades por medio del estudio y, gracias a ellas, avanza hacia la humanidad».`]},"ph-analects-13-19":{e:`app-es-secular`,t:[`Fan Chi preguntó por la humanidad. El Maestro dijo: «Muestra respeto en la vida privada, cuidado en los asuntos y sinceridad en el trato con los demás».`]},"ph-analects-13-23":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble busca armonía, no uniformidad; la persona mezquina busca uniformidad, no armonía».`]},"ph-analects-13-26":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble está serena sin ser arrogante; la persona mezquina es arrogante sin estar serena».`]},"ph-analects-13-27":{e:`app-es-secular`,t:[`El Maestro dijo: «La firmeza, la determinación, la sencillez y la parquedad al hablar están cerca de la humanidad».`]},"ph-analects-14-10":{e:`app-es-secular`,t:[`El Maestro dijo: «Ser pobre sin resentimiento es difícil; ser rico sin arrogancia es fácil».`]},"ph-analects-14-24":{e:`app-es-secular`,t:[`El Maestro dijo: «Antes la gente aprendía para mejorarse; hoy aprende para impresionar a los demás».`]},"ph-meditations-6-26":{e:`app-es-secular`,t:[`Si alguien te pregunta cómo se escribe el nombre «Antonino», ¿le gritarás cada letra? Si se enoja, ¿te enojarás también? ¿No se las dirás con calma, una por una? Así en la vida: recuerda que toda tarea se compone de pequeños pasos. Síguelos sin inquietarte, sin responder al enojo con enojo, y avanza paso a paso en lo que tienes delante.`]},"ph-meditations-7-2":{e:`app-es-secular`,t:[`Tus principios no pueden morir a menos que se apaguen los pensamientos que los mantienen vivos, y de ti depende volver a encenderlos una y otra vez. Puedes revivir. Mira de nuevo las cosas como antes las veías: eso es volver a vivir.`]},"ph-meditations-7-28":{e:`app-es-secular`,t:[`Recógete en ti. La razón que nos guía se basta a sí misma por naturaleza cuando obra con justicia y así encuentra la calma.`]},"ph-meditations-7-63":{e:`app-es-secular`,t:[`Se dice que ninguna alma se priva de la verdad por propia voluntad. Lo mismo ocurre con la justicia, la templanza, la bondad y demás. Tenlo siempre presente y tendrás más benevolencia con todo el mundo.`]},"ph-meditations-7-67":{e:`app-es-secular`,t:[`Aunque hayas perdido la esperanza de llegar a ser una gran figura de las letras o las ciencias, no renuncies a ser una persona libre, modesta, sociable y fiel al buen camino. Y recuerda siempre esto: se necesita muy poco para vivir una vida feliz.`]},"ph-meditations-8-22":{e:`app-es-secular`,t:[`Presta toda tu atención a lo que tienes delante, sea una acción, un principio o el sentido de unas palabras.`]},"ph-meditations-8-32":{e:`app-es-secular`,t:[`Debes construir tu vida acción por acción, y conformarte si cada acción cumple su parte en la medida de lo posible. Y nadie puede impedir que cada acción cumpla su parte.`]},"ph-meditations-8-40":{e:`app-es-secular`,t:[`Quita tu juicio sobre lo que parece doloroso, y quedarás a salvo por completo.`]},"ph-meditations-10-1":{e:`app-es-secular`,t:[`Alma mía, ¿serás algún día buena, sencilla, entera y transparente, más clara que el cuerpo que te envuelve? ¿Probarás algún día un ánimo afectuoso y amable? ¿Estarás algún día plena, sin que te falte nada, sin anhelar nada?`]},"ph-meditations-10-30":{e:`app-es-secular`,t:[`Cuando te moleste la falta de alguien, vuélvete enseguida hacia ti y considera si no has cometido un error parecido. Pronto se te pasará el enojo.`]},"ph-meditations-10-32":{e:`app-es-secular`,t:[`Que nadie pueda decir con verdad que no eres una persona sencilla o buena. Si alguien lo piensa, que sea falso. Todo esto está en tu mano.`]},"ph-meditations-11-4":{e:`app-es-secular`,t:[`¿He hecho algo por el bien común? Entonces ya he recibido mi recompensa. Ten esto siempre presente y nunca te detengas.`]},"ph-meditations-4-26":{e:`app-es-secular`,t:[`¿Te ha pasado algo? Está bien. Todo lo que sucede fue tejido desde el principio en el conjunto como tu parte. En suma, la vida es breve. Aprovecha el presente con buen juicio y justicia. Mantén la mente clara incluso al descansar.`]},"ph-meditations-5-3":{e:`app-es-secular`,t:[`Considera que mereces toda palabra y acción conforme a la naturaleza, y no te dejes llevar por las críticas o los comentarios que puedan venir después. Si es bueno hacerlo o decirlo, no lo creas indigno de ti.`]},"ph-meditations-5-22":{e:`app-es-secular`,t:[`Lo que no daña a la comunidad no daña a sus miembros. Cada vez que creas haber sufrido daño, aplica esta regla: si la comunidad no ha sufrido daño, yo tampoco.`]},"ph-meditations-5-31":{e:`app-es-secular`,t:[`¿Cómo te has portado hasta ahora con tus padres, hermanos, pareja, hijos, maestros, quienes te criaron, amistades y vecinos? ¿Puedes decir que hasta hoy no has hecho mal a ninguno de palabra ni de obra?`]},"ph-meditations-6-20":{e:`app-es-secular`,t:[`En el gimnasio, si alguien nos araña con las uñas o nos golpea la cabeza, no nos enojamos, ni guardamos rencor, ni sospechamos mala intención. Solo tenemos cuidado, sin hostilidad ni sospecha, apartándonos de buen humor. Hagamos lo mismo en el resto de la vida y pasemos por alto mucho de quienes compiten con nosotros.`]},"ph-meditations-6-42":{e:`app-es-secular`,t:[`Todos colaboramos hacia un mismo fin, unos a sabiendas y con comprensión, otros sin saberlo. Como se ha dicho, incluso quienes duermen son trabajadores que ayudan a que suceda lo que pasa en el mundo.`]},"ph-meditations-7-36":{e:`app-es-secular`,t:[`Es propio de la realeza hacer el bien y oír hablar mal de uno.`]},"ph-meditations-9-13":{e:`app-es-secular`,t:[`Hoy me he librado de toda inquietud; mejor dicho, la he echado fuera, porque no estaba fuera de mí, sino dentro, en mis propios juicios.`]},"ph-meditations-9-27":{e:`app-es-secular`,t:[`Cuando otros te culpen, te odien o digan cosas así de ti, entra en sus almas y mira qué clase de personas son. Verás que no necesitas inquietarte por lo que piensen de ti. Aun así, debes tratarles con benevolencia, porque por naturaleza son tus amigos.`]},"ph-meditations-12-17":{e:`app-es-secular`,t:[`Si no es correcto, no lo hagas; si no es verdad, no lo digas.`]},"ph-meditations-8-49":{e:`app-es-secular`,t:[`No te digas más de lo que te dicen las primeras impresiones. Te cuentan que alguien habla mal de ti. Eso es lo que te han contado; no te han contado que hayas sufrido daño. Quédate con las primeras impresiones, no añadas nada por dentro, y nada te sucede.`]},"ph-meditations-4-12":{e:`app-es-secular`,t:[`Ten siempre dos cosas preparadas: primero, hacer solo lo que la razón indique para el bien de las personas; segundo, cambiar de opinión si alguien te corrige y te aparta de una idea. Pero el cambio debe nacer del convencimiento de que es justo o útil para el bien común, no de que resulte agradable o dé buena fama.`]},"ph-meditations-7-58":{e:`app-es-secular`,t:[`Pase lo que pase, ten presentes a quienes les sucedió lo mismo y cómo se afligieron, lo vieron extraño y se quejaron. ¿Por qué querrías ser como ellos? Pon más bien toda tu atención en cómo aprovecharlo bien. Entonces se convertirá en material con el que trabajar.`]},"ph-meditations-8-26":{e:`app-es-secular`,t:[`La alegría de una persona está en hacer lo propio de un ser humano: buena voluntad hacia sus semejantes, elevarse sobre el tirón de los sentidos, discernir las impresiones engañosas y contemplar el orden de la naturaleza.`]},"ph-meditations-3-5":{e:`app-es-secular`,t:[`No actúes de mala gana, ni sin pensar en el bien común, ni sin la debida reflexión. No adornes tus pensamientos con palabras finas, ni hables demasiado, ni abarques demasiado. Ten buen ánimo y no dependas de ayuda externa ni de la calma que otros te den. Mantente en pie por ti, sin que otros te sostengan.`]},"ph-meditations-8-50":{e:`app-es-secular`,t:[`¿El pepino está amargo? Tíralo. ¿Hay zarzas en el camino? Rodéalas. Con eso basta. No añadas: «¿Por qué existen estas cosas en el mundo?».`]},"ph-analects-14-27":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble se avergüenza cuando sus palabras van más allá de sus actos».`]},"ph-analects-14-30":{e:`app-es-secular`,t:[`El Maestro dijo: «No te preocupes de que los demás no te conozcan; preocúpate de lo que aún no eres capaz de hacer».`]},"ph-analects-14-34":{e:`app-es-secular`,t:[`Alguien dijo: «¿Qué tal devolver el agravio con bondad?». El Maestro dijo: «¿Y entonces con qué devolverías la bondad? Devuelve el agravio con rectitud, y la bondad con bondad».`]},"ph-analects-14-35":{e:`app-es-secular`,t:[`El Maestro dijo: «¡Nadie me comprende!». Zigong dijo: «¿Por qué dice que nadie le comprende?». El Maestro dijo: «No me quejo del Cielo ni culpo a la gente. Aprendo de lo sencillo y avanzo hacia lo elevado. Si algo me comprende, es el Cielo».`]},"ph-analects-15-10":{e:`app-es-secular`,t:[`Zigong preguntó cómo practicar la humanidad. El Maestro dijo: «Quien quiere hacer bien su oficio debe primero afilar sus herramientas. Dondequiera que vivas, sirve a quienes más valen entre sus funcionarios y haz amistad con quienes más humanidad tienen entre sus letrados».`]},"ph-analects-15-12":{e:`app-es-secular`,t:[`El Maestro dijo: «Quien no piensa a largo plazo tendrá sin duda problemas a la vuelta de la esquina».`]},"ph-analects-15-18":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble toma lo justo como su sustancia, lo lleva a cabo con decoro, lo expresa con modestia y lo completa con confianza. ¡Así es una persona noble!».`]},"ph-analects-15-19":{e:`app-es-secular`,t:[`El Maestro dijo: «A la persona noble le preocupa su propia falta de capacidad, no que los demás no la reconozcan».`]},"ph-analects-15-21":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble busca la causa en sí; la persona mezquina la busca en los demás».`]},"ph-analects-15-22":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble es digna pero no pelea; es sociable pero no toma partido».`]},"ph-analects-15-23":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble no promueve a nadie solo por sus palabras, ni rechaza buenas palabras por quién las dijo».`]},"ph-analects-15-27":{e:`app-es-secular`,t:[`El Maestro dijo: «Las palabras astutas perturban la virtud. La falta de paciencia en lo pequeño desbarata los grandes planes».`]},"ph-analects-15-28":{e:`app-es-secular`,t:[`El Maestro dijo: «Cuando todos rechazan a alguien, hay que examinarlo; cuando todos aprecian a alguien, hay que examinarlo».`]},"ph-analects-15-29":{e:`app-es-secular`,t:[`El Maestro dijo: «Son las personas las que pueden ensanchar el camino, no el camino el que ensancha a las personas».`]},"ph-analects-15-30":{e:`app-es-secular`,t:[`El Maestro dijo: «Equivocarse y no corregirse: ese es el verdadero error».`]},"ph-analects-15-31":{e:`app-es-secular`,t:[`El Maestro dijo: «Una vez pasé un día entero sin comer y una noche entera sin dormir, solo pensando. No sirvió de nada. Es mejor aprender».`]},"ph-analects-15-36":{e:`app-es-secular`,t:[`El Maestro dijo: «Cuando se trata de obrar con humanidad, no cedas el paso ni a tu maestro».`]},"ph-analects-16-4":{e:`app-es-secular`,t:[`El Maestro dijo: «Hay tres clases de amistades que te ayudan y tres que te perjudican. Las rectas, las sinceras y las bien informadas te ayudan. Las ostentosas, las aduladoras y las de lengua fácil te perjudican».`]},"ph-analects-16-5":{e:`app-es-secular`,t:[`El Maestro dijo: «Hay tres clases de deleite que te ayudan y tres que te perjudican. Deleitarse en vivir con la medida del decoro y la música, en hablar de lo bueno de los demás y en tener muchas amistades valiosas: eso ayuda. Deleitarse en la arrogancia, en el ocio sin rumbo y en los banquetes: eso perjudica».`]},"ph-analects-16-10":{e:`app-es-secular`,t:[`El Maestro dijo: «La persona noble piensa en nueve cosas: al mirar, ver con claridad; al oír, escuchar bien; en el semblante, ser amable; en el porte, ser respetuosa; al hablar, ser sincera; en el trabajo, ser cuidadosa; ante la duda, preguntar; ante la ira, pensar en los problemas que traerá; y ante una ganancia, pensar si es justa».`]},"ph-analects-17-2":{e:`app-es-secular`,t:[`El Maestro dijo: «Por naturaleza las personas son parecidas; por la práctica se van alejando».`]},"ph-analects-17-6":{e:`app-es-secular`,t:[`Zizhang preguntó a Confucio por la humanidad. Confucio dijo: «Poder practicar cinco cosas en todas partes es humanidad». Al preguntarle cuáles eran, dijo: «Cortesía, generosidad, confianza, diligencia y bondad. Con cortesía no te menospreciarán; con generosidad ganarás a la gente; con confianza contarán contigo; con diligencia lograrás resultados; con bondad podrás guiar a otros».`]},"ph-analects-19-5":{e:`app-es-secular`,t:[`Zixia dijo: «Aprender cada día lo que no sabías y cada mes no olvidar lo que dominas: eso puede llamarse amar el aprendizaje».`]},"ph-analects-19-6":{e:`app-es-secular`,t:[`Zixia dijo: «Estudia con amplitud y mantén firme tu propósito; pregunta con interés y reflexiona sobre lo cercano. Ahí está la humanidad».`]},"ph-analects-19-7":{e:`app-es-secular`,t:[`Zixia dijo: «Los artesanos permanecen en su taller para completar su obra; la persona noble aprende para alcanzar el camino».`]},"ph-analects-19-21":{e:`app-es-secular`,t:[`Zigong dijo: «Las faltas de la persona noble son como los eclipses de sol y de luna. Cuando se equivoca, todo el mundo lo ve; cuando se corrige, todo el mundo la admira».`]},"ph-enchiridion-1":{e:`app-es-secular`,t:[`Algunas cosas dependen de nosotros y otras no. De nosotros dependen el juicio, el impulso, el deseo y la aversión: en suma, todo lo que es obra nuestra. No dependen de nosotros el cuerpo, las posesiones, la reputación, los cargos: en suma, todo lo que no es obra nuestra.`]},"ph-enchiridion-4":{e:`app-es-secular`,t:[`Cada vez que vayas a hacer algo, recuerda en qué consiste. Si vas a los baños, imagina lo que allí ocurre: gente que salpica, empuja, grita, se lleva cosas. Lo harás con más calma si dices: «Quiero bañarme y también mantener mi ánimo en armonía con la naturaleza». Hazlo así en cada empresa.`]},"ph-enchiridion-6":{e:`app-es-secular`,t:[`No te enorgullezcas de una excelencia que no es tuya. Si un caballo presumiera diciendo «soy hermoso», se podría tolerar. Pero cuando presumes diciendo «tengo un caballo hermoso», sabe que presumes de un bien que pertenece al caballo. ¿Qué es, entonces, lo tuyo? El uso que haces de tus impresiones.`]},"ph-enchiridion-8":{e:`app-es-secular`,t:[`No desees que las cosas sucedan como quieres; desea que sucedan como suceden, y tu vida fluirá en paz.`]},"ph-enchiridion-9":{e:`app-es-secular`,t:[`La enfermedad es un obstáculo para el cuerpo, pero no para la voluntad, a menos que ella misma lo quiera. La cojera es un obstáculo para la pierna, pero no para la voluntad. Dite esto ante todo lo que suceda y verás que es un obstáculo para otra cosa, pero no para ti.`]},"ph-enchiridion-13":{e:`app-es-secular`,t:[`Si quieres progresar, acepta parecer ignorante y torpe en las cosas externas. No quieras aparentar que sabes algo. Y si alguien te cree una persona especial, desconfía de ti.`]},"ph-enchiridion-15":{e:`app-es-secular`,t:[`Compórtate en la vida como en un banquete. Cuando una fuente llegue hasta ti, extiende la mano y sírvete con moderación. Si pasa de largo, no la retengas. Si aún no ha llegado, no estires tu deseo hacia ella; espera a que llegue.`]},"ph-enchiridion-17":{e:`app-es-secular`,t:[`Recuerda que eres intérprete en una obra, breve o larga según quiera su autor. Te toque el papel de una persona pobre, de alguien con una discapacidad, de quien gobierna o de alguien común, represéntalo bien. Lo tuyo es interpretar bien el papel que te dan; elegirlo le corresponde a otro.`]},"ph-enchiridion-20":{e:`app-es-secular`,t:[`Recuerda que no te ofende quien te insulta o golpea, sino tu juicio de que te ofende. Cuando alguien te provoque, sabe que es tu propia opinión la que te ha provocado. Así que, ante todo, procura no dejarte arrastrar enseguida por la impresión. Si ganas tiempo y haces una pausa, te dominarás con más facilidad.`]},"ph-enchiridion-22":{e:`app-es-secular`,t:[`Si quieres seguir el camino de la sabiduría, prepárate desde el principio para las burlas. Muchos se reirán diciendo: «¡De repente nos ha vuelto con aires de filosofía!». Pero no te des importancia; aférrate a lo que te parece mejor. Si te mantienes firme, quienes se rieron al principio acabarán respetándote.`]},"ph-enchiridion-29":{e:`app-es-secular`,t:[`En toda empresa, considera lo que viene antes y lo que sigue, y solo entonces empieza. Si no, comenzarás con entusiasmo, pero cuando más tarde aparezcan las dificultades, abandonarás con vergüenza.`]},"ph-enchiridion-30":{e:`app-es-secular`,t:[`Nuestros deberes se miden en general por nuestras relaciones. Si se trata de un padre, el deber es cuidarlo, cederle en todo y soportarlo cuando reprende. «Pero es un mal padre». ¿Estabas destinado por naturaleza a un buen padre? No, solo a un padre. «Mi hermano me hace daño». Entonces conserva tu lugar ante él. No mires lo que él hace, sino lo que debes hacer tú para que tu ánimo esté en armonía con la naturaleza.`]},"ph-enchiridion-33":{e:`app-es-secular`,t:[`Fíjate un carácter y una forma de ser que mantengas a solas y en compañía. Casi siempre guarda silencio, o di solo lo necesario y con pocas palabras. No rías mucho, ni de muchas cosas, ni sin medida. Evita por completo los juramentos si puedes; si no, en la medida de lo posible.`]},"ph-enchiridion-42":{e:`app-es-secular`,t:[`Cuando alguien te trate mal o hable mal de ti, recuerda que lo hace porque cree que es lo correcto. No puede seguir lo que a ti te parece correcto, sino lo que le parece a esa persona. Si juzga mal, es ella quien sale dañada, porque es quien se engaña. Partiendo de aquí, tendrás mansedumbre con quien te insulte. Cada vez, di: «Así le pareció».`]},"ph-enchiridion-43":{e:`app-es-secular`,t:[`Todo tiene dos asas: una por la que se puede llevar y otra por la que no. Si tu hermano te hace daño, no lo tomes por el asa de «me hace daño», porque por esa no se puede llevar. Tómalo más bien por la otra: «es mi hermano, crecimos juntos». Así podrás llevarlo.`]},"ph-enchiridion-48":{e:`app-es-secular`,t:[`Estas son las señales de quien progresa: no critica a nadie, no culpa a nadie, no se queja de nadie. No se presenta como alguien importante ni como quien sabe algo. Cuando le alaban, sonríe por dentro ante quien le alaba; cuando le reprochan, no se defiende.`]},"ph-enchiridion-51":{e:`app-es-secular`,t:[`¿Hasta cuándo aplazarás exigirte lo mejor? Ya has aceptado los principios que debes seguir. ¿Qué maestro sigues esperando? Ya no eres una criatura. Desde hoy, considera que mereces vivir como una persona adulta que progresa.`]},"ph-franklin-2":{e:`app-es-secular`,t:[`Silencio. No hables sino de lo que pueda beneficiar a otros o a ti; evita la conversación trivial.`]},"ph-franklin-3":{e:`app-es-secular`,t:[`Orden. Que todas tus cosas tengan su lugar; que cada parte de tus asuntos tenga su momento.`]},"ph-franklin-4":{e:`app-es-secular`,t:[`Resolución. Resuelve hacer lo que debes; haz sin falta lo que resuelvas.`]},"ph-franklin-5":{e:`app-es-secular`,t:[`Frugalidad. No gastes sino para hacer bien a otros o a ti; es decir, no malgastes nada.`]},"ph-franklin-7":{e:`app-es-secular`,t:[`Sinceridad. No uses engaños que hagan daño; piensa con inocencia y justicia, y si hablas, habla en consecuencia.`]},"ph-franklin-8":{e:`app-es-secular`,t:[`Justicia. No perjudiques a nadie causándole daño u omitiendo los beneficios que te corresponde dar.`]},"ph-franklin-9":{e:`app-es-secular`,t:[`Moderación. Evita los extremos; abstente de guardar rencor por los agravios tanto como crees que merecen.`]},"ph-franklin-10":{e:`app-es-secular`,t:[`Limpieza. No toleres la suciedad en el cuerpo, la ropa ni la vivienda.`]},"ph-franklin-11":{e:`app-es-secular`,t:[`Serenidad. No te inquietes por nimiedades ni por los percances comunes o inevitables.`]},"ph-mencius-3-6":{e:`app-es-secular`,t:[`El corazón compasivo es el brote de la humanidad; el corazón que siente vergüenza es el brote de la rectitud; el corazón que cede es el brote del decoro; el corazón que distingue lo justo de lo injusto es el brote de la sabiduría.`]},"ph-mencius-3-7":{e:`app-es-secular`,t:[`La persona humana es como quien tira con arco: corrige su postura antes de disparar. Si falla, no guarda rencor a quien le ha ganado, sino que se vuelve hacia sí y busca en sí la causa.`]},"ph-mencius-3-2":{e:`app-es-secular`,t:[`Mencio dijo: «Entiendo las palabras y sé cultivar bien mi energía vasta como un torrente».`]},"ph-mencius-6-2":{e:`app-es-secular`,t:[`La riqueza y los honores no pueden corromperle, la pobreza y la humildad no pueden moverle, el poder y la fuerza no pueden doblegarle. A una persona así se la llama verdaderamente grande.`]},"ph-mencius-7-4":{e:`app-es-secular`,t:[`Mencio dijo: «Si amas a los demás y no se te acercan, revisa tu humanidad. Si guías a otros y no se dejan guiar, revisa tu sabiduría. Si tratas a otros con cortesía y no responden, revisa tu respeto. Siempre que no obtengas lo que buscas, vuélvete y mira dentro. Cuando tú eres recto, el mundo se vuelve hacia ti».`]},"ph-mencius-7-10":{e:`app-es-secular`,t:[`Mencio dijo: «No se puede hablar con quien se daña a sí, ni trabajar con quien se abandona a sí. La humanidad es el hogar tranquilo de la persona; la rectitud, su camino correcto. Dejar vacío el hogar tranquilo sin habitarlo, abandonar el camino correcto sin recorrerlo: ¡qué pena!».`]},"ph-mencius-8-12":{e:`app-es-secular`,t:[`Mencio dijo: «Una gran persona es la que no ha perdido el corazón de la infancia».`]},"ph-mencius-8-28":{e:`app-es-secular`,t:[`Quien tiene humanidad ama a los demás; quien tiene decoro respeta a los demás. A quien ama a los demás, los demás siempre le aman; a quien respeta a los demás, los demás siempre le respetan.`]},"ph-mencius-8-8":{e:`app-es-secular`,t:[`Mencio dijo: «Solo cuando hay cosas que una persona no hará puede hacer algo que valga la pena».`]},"ph-mencius-8-14":{e:`app-es-secular`,t:[`Mencio dijo: «La persona noble profundiza en el camino porque quiere hallarlo por sí. Cuando lo hallas por ti, habitas en él con calma; habitando con calma, bebes de él a fondo; bebiendo a fondo, encuentras su fuente adondequiera que vayas. Por eso la persona noble quiere hallarlo por sí».`]},"ph-mencius-11-11":{e:`app-es-secular`,t:[`Cuando la gente pierde sus gallinas o sus perros, sabe ir a buscarlos; pero cuando pierde el corazón, no sabe buscarlo. El camino del aprendizaje no es otro que buscar el corazón perdido.`]},"ph-mencius-13-9":{e:`app-es-secular`,t:[`Cuando la gente de antaño podía realizar sus aspiraciones, extendía su bondad al pueblo; cuando no podía, se cultivaba y lo mostraba al mundo. En tiempos difíciles, hazte bien a ti; cuando las cosas van bien, comparte el bien con todo el mundo.`]},"ph-mencius-13-20":{e:`app-es-secular`,t:[`Mencio dijo: «La persona noble tiene tres alegrías, y gobernar el mundo no está entre ellas. Que vivan sus padres y sus hermanos estén bien: esa es la primera. Mirar al Cielo sin vergüenza y mirar a la gente sin vergüenza: esa es la segunda. Encontrar a los talentos del mundo y enseñarles: esa es la tercera».`]},"ph-mencius-13-4":{e:`app-es-secular`,t:[`Mencio dijo: «Todas las cosas están completas en mí. No hay mayor alegría que mirar dentro y hallar sinceridad. Esfuérzate por obrar comprendiendo a los demás, y no hay camino más corto hacia la humanidad».`]},"ph-mencius-13-6":{e:`app-es-secular`,t:[`Mencio dijo: «Una persona no debe carecer de vergüenza. Si te avergüenzas de no tener vergüenza, no tendrás nada de qué avergonzarte».`]},"ph-mencius-13-24":{e:`app-es-secular`,t:[`El agua que corre no sigue adelante hasta haber llenado cada hondonada. Así, cuando la persona noble pone su corazón en el camino, no llega más lejos hasta completar cada etapa.`]},"ph-mencius-14-35":{e:`app-es-secular`,t:[`Mencio dijo: «Para nutrir el corazón, nada es mejor que tener pocos deseos. Quien tiene pocos deseos puede perder algo de sí, pero poco; quien tiene muchos deseos puede conservar algo de sí, pero poco».`]},"ph-mencius-2-1":{e:`app-es-secular`,t:[`Mencio preguntó: «¿Qué es más grato, disfrutar de la música a solas o disfrutarla con otros?». El rey respondió: «No es tan grato como disfrutarla con otros».`]},"ph-mencius-4-1":{e:`app-es-secular`,t:[`Mencio dijo: «El momento favorable del Cielo no vale tanto como la ventaja del terreno, y la ventaja del terreno no vale tanto como la armonía entre las personas».`]},"ph-mencius-7-23":{e:`app-es-secular`,t:[`Mencio dijo: «El mal de la gente es que le gusta hacer de maestra de los demás».`]},"ph-mencius-13-15":{e:`app-es-secular`,t:[`Mencio dijo: «Lo que la gente puede hacer sin aprender es su capacidad innata; lo que sabe sin pensarlo es su conocimiento innato. No hay criatura que no sepa amar a sus padres, ni quien, al crecer, no sepa respetar a sus hermanos mayores».`]},"ph-zhongyong-1":{e:`app-es-secular`,t:[`Nada es más visible que lo oculto, nada más evidente que lo pequeño. Por eso la persona noble es cuidadosa cuando está a solas.`]},"ph-zhongyong-2":{e:`app-es-secular`,t:[`Confucio dijo: «La persona noble se mantiene en el justo medio; la persona mezquina va contra él. El justo medio de la persona noble consiste en encontrar siempre lo que conviene al momento; la mezquina va contra él porque no tiene freno».`]},"ph-zhongyong-13":{e:`app-es-secular`,t:[`La entrega sincera y la comprensión hacia los demás no están lejos del camino. Lo que no quisieras que te hicieran, no se lo hagas a los demás.`]},"ph-zhongyong-15":{e:`app-es-secular`,t:[`El camino de la persona noble es así: para llegar lejos hay que partir de lo cercano; para subir alto hay que empezar desde abajo.`]},"ph-zhongyong-27":{e:`app-es-secular`,t:[`La persona noble honra su naturaleza virtuosa y sigue el camino de la pregunta y el estudio; alcanza lo amplio y grande sin descuidar lo fino y sutil; llega a lo elevado y luminoso manteniéndose en el justo medio. Repasa lo antiguo para comprender lo nuevo y, con afecto sincero, honra el decoro.`]},"ph-zhongyong-33":{e:`app-es-secular`,t:[`Se lleva una túnica sencilla sobre la seda bordada porque no gusta que el dibujo resalte demasiado. Así, el camino de la persona noble es discreto pero brilla más cada día; el de la persona mezquina es llamativo pero se apaga cada día.`]},"ph-seneca-3":{e:`app-es-secular`,t:[`Piensa mucho antes de hacer de alguien tu amistad. Pero, una vez decidido, recíbele con todo el corazón y háblale con la misma franqueza con que te hablarías a ti.`]},"ph-seneca-5":{e:`app-es-secular`,t:[`Dejarás de temer cuando dejes de esperar. El temor y la esperanza van encadenados y caminan juntos. Ambos nacen cuando la mente se pierde en un futuro que aún no ha llegado.`]},"ph-seneca-7":{e:`app-es-secular`,t:[`Trata con quienes te harán mejor y acoge a quienes tú puedes hacer mejores. Esto es recíproco, porque las personas aprenden mientras enseñan.`]},"ph-seneca-9":{e:`app-es-secular`,t:[`Te mostraré un hechizo de amor sin pociones, sin hierbas, sin conjuros: si quieres que te amen, ama.`]},"ph-seneca-12":{e:`app-es-secular`,t:[`Apreciemos y amemos la edad madura, porque está llena de placer si se sabe aprovechar. La fruta sabe mejor cuando está bien madura. Trata cada día como una vida completa en sí.`]},"ph-seneca-16":{e:`app-es-secular`,t:[`Si vives según la naturaleza, nunca vivirás en pobreza; si vives según la opinión ajena, nunca tendrás riqueza. La naturaleza pide poco; la opinión no tiene fin.`]},"ph-seneca-18":{e:`app-es-secular`,t:[`Reserva unos días en los que te conformes con la comida más sencilla y ropa basta, y pregúntate: «¿Era esto lo que temía?». Es en tiempos de bienestar cuando la mente debe prepararse para la dificultad.`]},"ph-seneca-23":{e:`app-es-secular`,t:[`Ante todo, aprende a sentir alegría. La verdadera alegría no es risa ni charla; es algo serio. No viene de fuera, sino que brota de dentro. Mira el bien que hay en ti; eso es de verdad tuyo.`]},"ph-seneca-28":{e:`app-es-secular`,t:[`Te sorprende que tantos viajes y cambios de lugar no te hayan quitado el peso del corazón. Lo que necesitas es cambiar de ánimo, no de cielo, porque adondequiera que vayas, te llevas a ti contigo.`]},"ph-seneca-40":{e:`app-es-secular`,t:[`Gracias por escribirme tan a menudo, porque así me visitas de la única manera posible. La carta de una amistad ausente lleva huellas reales, pruebas reales de su presencia. Reconocer su letra es lo más dulce después de verse cara a cara.`]},"ph-seneca-48":{e:`app-es-secular`,t:[`Nadie puede vivir feliz si solo se mira a sí y lo convierte todo en provecho propio. Debes vivir para los demás si quieres vivir para ti.`]},"ph-seneca-50":{e:`app-es-secular`,t:[`¿Por qué nos engañamos? Nuestro mal no está fuera, sino dentro. Por eso cuesta sanar. Pero si queremos curarnos, nunca es demasiado tarde, porque la mente es flexible y se puede educar.`]},"ph-seneca-56":{e:`app-es-secular`,t:[`No hay verdadera quietud salvo la que ha traído la razón. ¿Qué importa cuánto ruido haya fuera, si dentro todo está en calma? Si la mente está en paz consigo, el alboroto exterior no puede alterarte.`]},"ph-seneca-71":{e:`app-es-secular`,t:[`Nuestros planes se tuercen porque no tienen meta. Para quien no sabe a qué puerto se dirige, ningún viento es favorable.`]},"ph-seneca-76":{e:`app-es-secular`,t:[`Hay que seguir aprendiendo mientras haya algo que no sepas; si creemos al refrán, mientras vivas.`]},"ph-seneca-78":{e:`app-es-secular`,t:[`El dolor demasiado grande para soportarlo no dura mucho, y el que dura mucho se puede soportar. Y todo es ligero si la opinión no le añade nada. No vuelvas a sufrir ahora recordando el dolor pasado.`]},"ph-seneca-98":{e:`app-es-secular`,t:[`La mente que se angustia por el futuro es desdichada: lo es antes de que llegue la desgracia. Lo mismo la que se inquieta porque lo bueno dure hasta el final. Una mente así nunca descansa y, mientras espera, pierde incluso lo que podría disfrutar ahora.`]},"ph-seneca-106":{e:`app-es-secular`,t:[`Malgastamos la fuerza del estudio en sutilezas inútiles. No aprendemos para la vida, sino para la escuela. Pero el aprendizaje debería ser para la vida.`]},"ph-seneca-107":{e:`app-es-secular`,t:[`Soporta con valor lo que no se puede evitar. Seguir entre quejas lo que no se puede cambiar es propio del peor soldado. El destino guía a quien lo acepta y arrastra a quien se resiste.`]},"ph-seneca-123":{e:`app-es-secular`,t:[`Nada es pesado si la mente lo acepta de buen grado. Lo que nos agota no es tanto la tarea como hacerla a regañadientes.`]},"ph-brevitate-1":{e:`app-es-secular`,t:[`No es que tengamos poco tiempo de vida, sino que desperdiciamos mucho. La vida es lo bastante larga, y da para las cosas más grandes, si se emplea bien.`]},"ph-brevitate-3":{e:`app-es-secular`,t:[`La gente es tacaña para guardar sus bienes, pero derrochadora con el tiempo, la única cosa en la que conviene el cuidado.`]},"ph-brevitate-7":{e:`app-es-secular`,t:[`Aprender a vivir lleva toda la vida. Así que no te apresures; sigue aprendiendo un poco cada día.`]},"ph-brevitate-14":{e:`app-es-secular`,t:[`Solo quienes dedican tiempo a la sabiduría tienen verdadero ocio. No solo cuidan bien su tiempo, sino que le suman todas las épocas pasadas. Toda la sabiduría reunida a lo largo de los años se vuelve suya. Los sabios de antaño siempre les reciben y no despiden a nadie con las manos vacías.`]},"ph-epicurus-17":{e:`app-es-secular`,t:[`No hay que felicitar a quien es joven, sino a quien es mayor y ha vivido bien. La juventud, en su plenitud, se ve zarandeada por la fortuna; la vejez echa el ancla como en un puerto y guarda a salvo, en grato recuerdo, los bienes que antes solo esperaba.`]},"ph-epicurus-35":{e:`app-es-secular`,t:[`No estropees lo que tienes deseando lo que no tienes; recuerda que lo que ahora tienes estuvo una vez entre las cosas que esperabas.`]},"ph-epicurus-34":{e:`app-es-secular`,t:[`No necesitamos tanto la ayuda de nuestras amistades como la confianza de poder contar con su ayuda.`]},"ph-daodejing-2":{e:`app-es-secular`,t:[`La persona sabia actúa sin forzar y enseña sin palabras. Deja que todo surja sin rechazarlo, da vida sin poseer, actúa sin apoyarse en ello y logra sin quedarse con el mérito. Precisamente porque no se queda con él, el mérito nunca se va.`]},"ph-daodejing-5":{e:`app-es-secular`,t:[`¿No es el espacio entre el cielo y la tierra como un fuelle? Vacío pero inagotable, cuanto más se mueve, más produce. Las muchas palabras pronto se agotan; mejor mantenerse en el centro.`]},"ph-daodejing-7":{e:`app-es-secular`,t:[`El cielo es duradero y la tierra perdura. Pueden durar tanto porque no viven para sí; por eso siguen viviendo. Así, la persona sabia se pone al final y sin embargo queda delante; se deja a un lado y sin embargo se conserva. ¿No es porque no tiene egoísmo que puede realizarse?`]},"ph-daodejing-8":{e:`app-es-secular`,t:[`El bien supremo es como el agua. El agua beneficia a todos los seres sin competir y se asienta en los lugares bajos que la gente evita. Por eso está cerca del camino. Al habitar, elige bien el suelo; en el corazón, ten hondura; al dar, ten bondad; al hablar, di la verdad. Porque no compite, no hay reproche.`]},"ph-daodejing-9":{e:`app-es-secular`,t:[`Llenar un recipiente hasta el borde no vale tanto como detenerse a tiempo. Un filo demasiado afilado no dura mucho. Una casa llena de oro y jade no se puede guardar; mejor detenerse. Riqueza y honores con arrogancia traen su propia ruina. Retirarse cuando la obra está hecha: ese es el camino del cielo.`]},"ph-daodejing-11":{e:`app-es-secular`,t:[`Treinta radios comparten un cubo, pero es el centro vacío lo que hace útil al carro. Se moldea el barro para hacer una vasija, pero es el hueco interior lo que la hace útil. Se abren puertas y ventanas para hacer una habitación, pero es el espacio vacío lo que la hace útil. Así, lo que hay da provecho; lo que no hay da utilidad.`]},"ph-daodejing-12":{e:`app-es-secular`,t:[`Los cinco colores ciegan los ojos, los cinco sonidos ensordecen los oídos, los cinco sabores embotan el paladar. Las carreras y la caza enloquecen la mente; los bienes raros extravían la conducta. Por eso la persona sabia cuida el vientre y no los ojos: deja aquello y toma esto.`]},"ph-daodejing-15":{e:`app-es-secular`,t:[`¿Quién puede dejar quieta el agua turbia para que poco a poco se aclare? ¿Quién puede mover lo que reposa para que poco a poco cobre vida? Quien sigue este camino no busca estar lleno.`]},"ph-daodejing-17":{e:`app-es-secular`,t:[`De los mejores líderes, la gente apenas sabe que existen. Después vienen aquellos a quienes se ama y alaba, luego aquellos a quienes se teme, luego aquellos a quienes se desprecia. Donde falta confianza, hay desconfianza. Sin prisa y parcos en palabras, los mejores terminan su obra, y la gente dice: «Ocurrió de manera natural, por sí solo».`]},"ph-daodejing-23":{e:`app-es-secular`,t:[`Hablar poco es lo natural. Un torbellino no dura toda la mañana; un aguacero no dura todo el día. ¿Quién los hace así? El cielo y la tierra. Si ni el cielo y la tierra pueden mantenerlos mucho tiempo, ¡cuánto menos las personas!`]},"ph-daodejing-24":{e:`app-es-secular`,t:[`Quien se pone de puntillas no se mantiene en pie mucho tiempo; quien da zancadas no llega lejos. Quien se exhibe no se ve con claridad; quien insiste en tener razón no brilla; quien se jacta no tiene mérito; quien se engrandece no perdura.`]},"ph-daodejing-26":{e:`app-es-secular`,t:[`Lo pesado es la raíz de lo ligero; la quietud es la dueña de la inquietud. Por eso la persona sabia viaja todo el día sin apartarse del carro de equipaje y, aunque haya espectáculos espléndidos, permanece tranquila y desapegada.`]},"ph-daodejing-27":{e:`app-es-secular`,t:[`La persona sabia siempre sabe ayudar a la gente, y así nadie queda abandonado; siempre sabe aprovechar las cosas, y así nada se desecha. Esto se llama continuar la luz. Así, la persona buena es maestra de quien no lo es, y quien no es bueno es la materia con que trabaja la persona buena.`]},"ph-daodejing-28":{e:`app-es-secular`,t:[`Conoce lo fuerte, pero mantente en lo suave, y serás un arroyo para el mundo. Siendo arroyo del mundo, la virtud constante no te abandona, y vuelves a ser como una criatura.`]},"ph-daodejing-34":{e:`app-es-secular`,t:[`La persona sabia puede alcanzar la grandeza porque nunca se considera grande. Por eso puede alcanzarla.`]},"ph-daodejing-37":{e:`app-es-secular`,t:[`Sin ansia y en quietud, el mundo se asentará por sí solo.`]},"ph-daodejing-40":{e:`app-es-secular`,t:[`El retorno es el movimiento del camino; la suavidad es su manera de obrar. Todas las cosas del mundo nacen del ser, y el ser nace del no ser.`]},"ph-daodejing-43":{e:`app-es-secular`,t:[`Lo más blando del mundo domina a lo más duro. Lo que no tiene forma entra donde no hay resquicio. Pocos en el mundo alcanzan la enseñanza sin palabras y el beneficio de no forzar.`]},"ph-daodejing-45":{e:`app-es-secular`,t:[`El movimiento vence al frío; la quietud vence al calor. La claridad y la quietud ponen en orden el mundo.`]},"ph-daodejing-46":{e:`app-es-secular`,t:[`No hay mayor desgracia que no saber cuándo es suficiente, ni mayor falta que querer siempre ganar. Por eso, la satisfacción de saber cuándo basta es una satisfacción duradera.`]},"ph-daodejing-47":{e:`app-es-secular`,t:[`Sin salir por la puerta se puede conocer el mundo; sin mirar por la ventana se puede ver el camino del cielo. Cuanto más lejos se va, menos se sabe.`]},"ph-daodejing-48":{e:`app-es-secular`,t:[`En el estudio, cada día se añade algo; en el camino, cada día se suelta algo. Soltando y volviendo a soltar, se llega a no forzar. Sin forzar, y sin embargo nada queda sin hacer.`]},"ph-daodejing-49":{e:`app-es-secular`,t:[`La persona sabia no tiene una mente fija propia y toma como suya la mente del pueblo. A quien es bueno, lo trato con bondad; a quien no lo es, también lo trato con bondad; así se alcanza la bondad. A quien es digno de confianza, le confío; a quien no lo es, también le confío; así se alcanza la confianza.`]},"ph-daodejing-52":{e:`app-es-secular`,t:[`Ver lo pequeño se llama claridad; mantenerse en la suavidad se llama fortaleza.`]},"ph-daodejing-54":{e:`app-es-secular`,t:[`Lo bien plantado no se arranca; lo bien abrazado no se escapa. Cultívalo en ti, y tu virtud será auténtica; en tu familia, y será abundante; en tu aldea, y será duradera; en tu país, y florecerá; en el mundo, y estará en todas partes.`]},"ph-daodejing-55":{e:`app-es-secular`,t:[`Quien guarda la virtud en abundancia es como un recién nacido.`]},"ph-daodejing-56":{e:`app-es-secular`,t:[`Quien sabe no habla; quien habla no sabe. Embota los filos, deshaz los nudos, suaviza el brillo, hazte uno con el polvo. A esto se le llama la unidad profunda.`]},"ph-daodejing-58":{e:`app-es-secular`,t:[`La buena fortuna se apoya en la desgracia; la desgracia se esconde en la buena fortuna. ¿Quién sabe dónde termina?`]},"ph-daodejing-59":{e:`app-es-secular`,t:[`Para cuidar de la gente y servir al cielo, nada mejor que la mesura. La mesura es prepararse temprano; prepararse temprano es acumular virtud una y otra vez. Cuando la virtud se acumula una y otra vez, no hay nada que no se pueda superar.`]},"ph-daodejing-60":{e:`app-es-secular`,t:[`Gobernar un gran país es como cocinar un pez pequeño.`]},"ph-daodejing-66":{e:`app-es-secular`,t:[`Los ríos y los mares pueden ser reyes de cien valles porque saben mantenerse abajo. Por eso pueden ser reyes de cien valles.`]},"ph-daodejing-67":{e:`app-es-secular`,t:[`Tengo tres tesoros que guardo y conservo. El primero es la compasión; el segundo, la sencillez; el tercero, no atreverme a ponerme delante de los demás. Con compasión se puede ser valiente; con sencillez se puede dar con amplitud; sin atreverse a ponerse delante, se puede guiar a gente capaz.`]},"ph-daodejing-70":{e:`app-es-secular`,t:[`Mis palabras son muy fáciles de entender y muy fáciles de practicar, pero nadie en el mundo las entiende ni las practica. Cuantos menos me conocen, más valioso soy. Por eso la persona sabia viste tela basta, pero lleva jade dentro.`]},"ph-daodejing-71":{e:`app-es-secular`,t:[`Saber y creer que no se sabe es lo más alto; no saber y creer que se sabe es una enfermedad. Solo reconociendo la enfermedad como tal se puede quedar libre de ella.`]},"ph-daodejing-77":{e:`app-es-secular`,t:[`¿No es el camino del cielo como tensar un arco? Lo alto se baja, lo bajo se eleva; lo que sobra se reduce, lo que falta se completa. El camino del cielo quita a lo que sobra y da a lo que falta.`]},"ph-daodejing-78":{e:`app-es-secular`,t:[`Nada en el mundo es más blando y débil que el agua, pero para desgastar lo duro y fuerte nada la supera, porque nada puede sustituirla. Que lo débil vence a lo fuerte y lo blando vence a lo duro, todo el mundo lo sabe, pero nadie lo pone en práctica.`]},"ph-daodejing-79":{e:`app-es-secular`,t:[`Aun cuando se resuelve un gran agravio, queda algo de resentimiento; ¿cómo llamar a eso un buen arreglo? Por eso la persona sabia guarda la mitad izquierda del recibo, pero no exige a nadie el pago. El camino del cielo no tiene favoritos; siempre está con quien obra bien.`]},"ph-ethics-1-7":{e:`app-es-secular`,t:[`Una golondrina no hace la primavera, ni tampoco un solo día de buen tiempo. Del mismo modo, un día o un breve tiempo no hacen a nadie dichoso y feliz.`]},"ph-ethics-1-10":{e:`app-es-secular`,t:[`Cuando alguien soporta con calma muchas y grandes desgracias, no por insensibilidad sino por generosidad y grandeza de ánimo, la nobleza brilla incluso en ellas.`]},"ph-ethics-2-1":{e:`app-es-secular`,t:[`Nos hacemos constructores construyendo y músicos tocando. Del mismo modo, adquirimos la justicia realizando actos justos, la moderación actuando con moderación y la valentía realizando actos valientes.`]},"ph-ethics-2-6":{e:`app-es-secular`,t:[`La virtud es un término medio entre dos defectos, uno por exceso y otro por defecto. Consiste en hallar y elegir lo adecuado en los sentimientos y en las acciones.`]},"ph-ethics-2-9":{e:`app-es-secular`,t:[`Cualquiera puede enojarse; eso es fácil. Pero enojarse con la persona adecuada, en la medida adecuada, en el momento adecuado, por el motivo adecuado y de la manera adecuada no está al alcance de todos ni es fácil.`]},"ph-ethics-3-5":{e:`app-es-secular`,t:[`La virtud depende de nosotros, y también el vicio. Porque donde está en nuestra mano actuar, también está en nuestra mano no actuar.`]},"ph-ethics-3-7":{e:`app-es-secular`,t:[`La persona valiente teme y soporta lo que debe, con el fin debido, de la manera debida y en el momento debido. Siente y actúa según lo que la situación merece y lo que la razón dicta, y su fin es lo noble.`]},"ph-ethics-4-1":{e:`app-es-secular`,t:[`La persona generosa da por amor a lo noble, y da bien: a quien corresponde, en la medida justa, en el momento oportuno, y con gusto, sin pesar.`]},"ph-ethics-8-1":{e:`app-es-secular`,t:[`Nadie elegiría vivir sin amistades, aunque tuviera todos los demás bienes. También en la pobreza y en otras desgracias, la gente considera que las amistades son su único refugio.`]},"ph-ethics-8-3":{e:`app-es-secular`,t:[`La amistad más completa es la que se da entre personas buenas y semejantes en virtud. Se desean el bien mutuamente porque cada una es buena. Estas amistades son raras, pero duran mientras sigan siendo buenas.`]},"ph-ethics-8-8":{e:`app-es-secular`,t:[`La amistad parece consistir más en amar que en recibir amor. Lo muestran las madres, que aman a sus hijos sin buscar ser correspondidas.`]},"ph-ethics-9-4":{e:`app-es-secular`,t:[`La persona buena se relaciona con su amistad como consigo, porque una amistad es otro yo.`]},"ph-ethics-9-9":{e:`app-es-secular`,t:[`Parece extraño decir que la persona feliz no necesita amistades. El ser humano está hecho para vivir con otros, así que también quien es feliz necesita compañía. La vida es dura para quien está a solas, pero con otros es más fácil mantenerse activo.`]},"ph-ethics-9-12":{e:`app-es-secular`,t:[`La amistad entre personas buenas es buena y crece con el trato. Parecen hacerse mejores al obrar juntas y corregirse mutuamente, porque cada una toma de la otra las cualidades que admira.`]},"ph-epicurus-23":{e:`app-es-secular`,t:[`Toda amistad es deseable por sí misma, aunque haya empezado por la ayuda que nos damos.`]},"ph-epicurus-27":{e:`app-es-secular`,t:[`En otras tareas el fruto llega solo después del esfuerzo, pero en el amor a la sabiduría el deleite va de la mano del conocimiento. La alegría no llega después de aprender; llega mientras se aprende.`]},"ph-epicurus-41":{e:`app-es-secular`,t:[`Hay que reír y amar la sabiduría al mismo tiempo, mientras se cuida de la casa y se atienden los demás asuntos, sin dejar nunca de decir las palabras de la verdadera sabiduría.`]},"ph-epicurus-52":{e:`app-es-secular`,t:[`La amistad danza alrededor del mundo y nos llama a todos a despertar y celebrar la vida feliz.`]},"ph-epicurus-66":{e:`app-es-secular`,t:[`Compartamos las penas de nuestras amistades, no lamentándonos, sino cuidándolas con atención.`]},"ph-amicitia-23":{e:`app-es-secular`,t:[`La amistad proyecta una esperanza luminosa sobre el futuro y no deja que el ánimo se debilite o caiga. Quien mira a una verdadera amistad ve, por así decirlo, su propio reflejo.`]},"ph-amicitia-44":{e:`app-es-secular`,t:[`Que esta sea la primera ley de la amistad: pide a tus amistades solo lo honesto y haz por ellas solo lo honesto. No esperes a que te pidan; ten disposición, sin vacilar, y el valor de dar consejos francos.`]},"ph-amicitia-47":{e:`app-es-secular`,t:[`Quienes quitan la amistad de la vida parecen quitar el sol del mundo, porque no hemos recibido nada mejor ni más grato que la amistad.`]},"ph-amicitia-80":{e:`app-es-secular`,t:[`Quien mira a una verdadera amistad mira a un segundo yo. Cada persona se ama a sí, no para obtener recompensa por ese amor, sino porque se tiene cariño. Si este mismo sentimiento no se traslada a la amistad, nunca se hallará una amistad verdadera.`]},"ph-amicitia-88":{e:`app-es-secular`,t:[`La naturaleza no ama nada solitario y siempre busca algún apoyo, y ese apoyo es más dulce cuando se encuentra en la amistad más querida.`]},"ph-amicitia-104":{e:`app-es-secular`,t:[`Ya que la amistad no puede existir sin virtud, aprecia mucho la virtud; y, aparte de la virtud, considera que nada es más excelente que la amistad.`]},"ph-pensees-277":{e:`app-es-secular`,t:[`El corazón tiene sus razones, que la razón no conoce.`]},"ph-pensees-172":{e:`app-es-secular`,t:[`Nunca nos quedamos en el presente. Anticipamos el futuro como si llegara demasiado despacio, como para apresurarlo, y llamamos al pasado para detenerlo, porque se escapa demasiado rápido. Así, nunca vivimos, sino que solo esperamos vivir.`]},"ph-pensees-397":{e:`app-es-secular`,t:[`La grandeza del ser humano está en saberse frágil. Un árbol no sabe que es frágil.`]},"ph-pensees-365":{e:`app-es-secular`,t:[`El pensamiento hace la grandeza del ser humano.`]},"ph-montaigne-1-14":{e:`app-es-secular`,t:[`El sabor del bien y del mal depende en buena parte de la opinión que tenemos de ellos. Lo que atormenta a las personas no son las cosas, sino sus opiniones sobre las cosas.`]},"ph-montaigne-1-26":{e:`app-es-secular`,t:[`A quien enseña hay que elegirle por tener la cabeza bien hecha más que bien llena. No hagas que el alumnado solo memorice y repita; deja que digiera lo que aprende y lo haga suyo.`]},"ph-montaigne-1-28":{e:`app-es-secular`,t:[`Si me insisten en que diga por qué le quería, siento que solo puedo responder: «Porque era él, porque era yo».`]},"ph-montaigne-1-39":{e:`app-es-secular`,t:[`Debemos reservarnos una trastienda toda nuestra, enteramente libre, en la que establecer nuestra verdadera libertad y nuestro principal retiro y soledad.`]},"ph-montaigne-3-2":{e:`app-es-secular`,t:[`Cada persona lleva en sí la forma entera de la condición humana.`]},"ph-montaigne-3-13":{e:`app-es-secular`,t:[`Somos muy necios. «Hoy no he hecho nada», decimos. ¿Cómo? ¿No has vivido? Esa no es solo la más fundamental, sino la más ilustre de tus ocupaciones.`]}};export{e as default};